-- LogySign › No firma: soporte de solicitud de firma digital (Config_Doc_Trabajador 100, SSFD).
-- 1. Dynamic_Logysign guarda cuándo, quién y con qué anotación se cerró un documento como No firma.
-- 2. Los registros ya cerrados como No firma (Maestro_docTrabajador logysign-<id> con la observación
--    'El trabajador no firma…') quedan marcados con la fecha de ese cierre, para poder generarles el soporte.
-- 3. Plantilla 'soporte_no_firma' en Maestro_Plantillas (HTML también en migraciones/plantillas/).
-- 4. Config_Parametros: documento del soporte y permiso de No firma igual al de eliminar pendientes
--    (quien creó el registro o el rol del parámetro, ahora solo Sistema).
-- Solo agrega columnas y filas y actualiza datos con WHERE preciso. Se puede ejecutar más de una vez.

SET @existe := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'Dynamic_Logysign' AND COLUMN_NAME = 'no_firma_fecha');
SET @sql := IF(@existe = 0, 'ALTER TABLE Dynamic_Logysign ADD COLUMN no_firma_fecha DATETIME NULL', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @existe := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'Dynamic_Logysign' AND COLUMN_NAME = 'no_firma_usuario');
SET @sql := IF(@existe = 0, 'ALTER TABLE Dynamic_Logysign ADD COLUMN no_firma_usuario VARCHAR(50) NULL', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @existe := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'Dynamic_Logysign' AND COLUMN_NAME = 'no_firma_anotacion');
SET @sql := IF(@existe = 0, 'ALTER TABLE Dynamic_Logysign ADD COLUMN no_firma_anotacion VARCHAR(500) NULL', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

UPDATE Dynamic_Logysign dl
JOIN Maestro_docTrabajador d ON d.id = CONCAT('logysign-', dl.id)
SET dl.no_firma_fecha = d.FechaRegistro + INTERVAL 5 HOUR -- FechaRegistro de LogySign quedaba 5 horas atrás (convert_tz desde SYSTEM con conexión en -05:00)
WHERE dl.estado = 'FIRMADO' AND dl.no_firma_fecha IS NULL AND d.Observaciones LIKE 'El trabajador no firma%';

INSERT INTO Maestro_Plantillas
  (nombre_proceso, id_config_doc, observaciones, codigo_formato, version_formato, fecha_version,
   tabla_datos, id_campo_fk, bucket_carpeta, requiere_firma_trabajador, activo, version, contenido_html)
SELECT 'soporte_no_firma', 100, 'Soporte de solicitud de firma digital (LogySign, No firma)', NULL, '1', '2026-11-26',
       'Dynamic_Logysign', 'id', 'talenthub_central', 0, 1, 1, '<style>\n  /* Estilos encerrados en .rdoc (mismo diseño de los documentos recientes). */\n  .rdoc { font-family: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, "Helvetica Neue", Arial, sans-serif; color: #0f172a; font-size: 9pt; line-height: 1.4; -webkit-font-smoothing: antialiased; }\n  .rdoc * { box-sizing: border-box; }\n  .rdoc p { margin: 0 0 8px 0; text-align: justify; }\n\n  .rdoc .doc-header-table { width: 100%; border-collapse: collapse; margin-bottom: 10px; border: 1px solid #cbd5e1; }\n  .rdoc .doc-header-table td { border: 1px solid #cbd5e1; vertical-align: middle; }\n  .rdoc .header-logo-cell { width: 24%; text-align: center; padding: 8px 10px; background: #ffffff; }\n  .rdoc .logo-img { height: 46px; max-width: 170px; object-fit: contain; display: block; margin: 0 auto; }\n  .rdoc .header-title-cell { width: 56%; background: #e6edf7; text-align: center; padding: 10px 14px; }\n  .rdoc .doc-title { font-size: 11pt; font-weight: 800; color: #000b59; letter-spacing: 0.4px; text-transform: uppercase; line-height: 1.25; }\n  .rdoc .doc-subtitle { font-size: 8pt; font-weight: 700; color: #c2410c; margin-top: 3px; text-transform: uppercase; letter-spacing: 0.3px; }\n  .rdoc .doc-subdetail { font-size: 7pt; color: #475569; font-weight: 600; margin-top: 2px; text-transform: uppercase; letter-spacing: 0.2px; }\n  .rdoc .header-meta-cell { width: 20%; padding: 6px 10px; font-size: 8pt; text-align: center; background: #f8fafc; color: #1e293b; line-height: 1.35; }\n  .rdoc .meta-code { font-weight: 800; color: #000b59; font-size: 8.5pt; }\n  .rdoc .meta-ver { color: #334155; }\n  .rdoc .meta-date { color: #64748b; font-size: 7.5pt; }\n\n  .rdoc .status-banner { display: table; width: 100%; border: 1px solid #fed7aa; background: #fff7ed; border-left: 4px solid #f55400; border-radius: 6px; padding: 6px 12px; margin-bottom: 10px; }\n  .rdoc .status-banner .label { font-size: 7.5pt; font-weight: 700; color: #9a3412; text-transform: uppercase; letter-spacing: 0.5px; }\n  .rdoc .status-banner .value { font-size: 10pt; font-weight: 800; color: #7c2d12; margin-top: 1px; }\n\n  .rdoc .section-block { margin-bottom: 9px; page-break-inside: avoid; }\n  .rdoc .section-title { font-size: 8.5pt; font-weight: 700; color: #000b59; text-transform: uppercase; letter-spacing: 0.6px; padding-bottom: 3px; border-bottom: 1px solid #e2e8f0; margin-bottom: 5px; }\n  .rdoc .section-title::before { content: \'\'; display: inline-block; width: 4px; height: 12px; background: #f55400; border-radius: 2px; margin-right: 6px; vertical-align: -1px; }\n\n  .rdoc .data-grid { width: 100%; border-collapse: separate; border-spacing: 0; border: 1px solid #e2e8f0; border-radius: 6px; overflow: hidden; font-size: 8.4pt; line-height: 1.3; }\n  .rdoc .data-grid td { padding: 3.5px 10px; border-bottom: 1px solid #f1f5f9; vertical-align: middle; }\n  .rdoc .data-grid tr:last-child td { border-bottom: none; }\n  .rdoc .data-grid tr:nth-child(even) td { background: #fafafa; }\n  .rdoc .data-label { width: 32%; font-weight: 700; color: #64748b; border-right: 1px solid #f1f5f9; }\n  .rdoc .data-val { font-weight: 600; color: #0f172a; word-break: break-word; }\n  .rdoc .data-val.mono { font-family: Consolas, "Courier New", monospace; font-size: 7.6pt; font-weight: 500; color: #334155; }\n\n  .rdoc .letter-body p { font-size: 8.8pt; margin-bottom: 8px; }\n  .rdoc .letter-body strong { color: #000b59; }\n\n  .rdoc .note-box { background: #f8fafc; border: 1px solid #e2e8f0; border-left: 3.5px solid #000b59; border-radius: 6px; padding: 6px 12px; margin: 2px 0 8px 0; }\n  .rdoc .note-box p { margin: 0 0 3px 0; font-size: 8.2pt; color: #334155; }\n  .rdoc .note-box p:last-child { margin-bottom: 0; }\n  .rdoc .note-box strong { color: #000b59; }\n  .rdoc .annotation { white-space: pre-line; font-weight: 700; color: #b91c1c; }\n\n  .rdoc .doc-footer { margin-top: 10px; text-align: center; }\n  .rdoc .doc-footer .line { height: 2px; background: #f55400; border-radius: 1px; margin-bottom: 7px; }\n  .rdoc .doc-footer .addr { color: #000b59; font-size: 7.5pt; line-height: 1.4; letter-spacing: 0.3px; }\n  .rdoc .doc-footer .legal { color: #94a3b8; font-size: 6.8pt; margin-top: 2px; }\n</style>\n\n<div class="rdoc">\n\n  <table class="doc-header-table">\n    <tr>\n      <td class="header-logo-cell"><img src="{{logo_src}}" alt="LOG&amp;SER" class="logo-img"></td>\n      <td class="header-title-cell">\n        <div class="doc-title">Soporte de solicitud de firma digital</div>\n        <div class="doc-subtitle">Gestión de Talento Humano</div>\n        <div class="doc-subdetail">Constancia de envío por correo electrónico — LogySign</div>\n      </td>\n      <td class="header-meta-cell">\n        <div class="meta-code">{{codigo_formato}}</div>\n        <div class="meta-ver">Versión {{version_formato}}</div>\n        <div class="meta-date">{{fecha_formato}}</div>\n      </td>\n    </tr>\n  </table>\n\n  <div class="status-banner">\n    <div class="label">Resultado de la solicitud</div>\n    <div class="value">El trabajador no firmó el documento — cerrado con soporte de correo electrónico</div>\n  </div>\n\n  <div class="letter-body">\n    <p><strong>APOYO LOGÍSTICO Y OPERATIVO SAS</strong> deja constancia de que el documento descrito a continuación fue puesto a disposición del trabajador para su revisión y firma digital a través de la plataforma <strong>LogySign</strong>, mediante un enlace personal notificado al correo electrónico registrado, y que el trabajador no lo firmó. En consecuencia, el documento se cerró con la anotación de soporte por correo electrónico que se indica en este soporte.</p>\n  </div>\n\n  <div class="section-block">\n    <div class="section-title">Datos del trabajador</div>\n    <table class="data-grid">\n      <tr><td class="data-label">Nombre</td><td class="data-val">{{nombre_trabajador}}</td></tr>\n      <tr><td class="data-label">Identificación</td><td class="data-val">{{identificacion}}</td></tr>\n      <tr><td class="data-label">Cargo</td><td class="data-val">{{cargo}}</td></tr>\n      <tr><td class="data-label">Operación / Regional</td><td class="data-val">{{operacion}} / {{regional}}</td></tr>\n    </table>\n  </div>\n\n  <div class="section-block">\n    <div class="section-title">Solicitud de firma</div>\n    <table class="data-grid">\n      <tr><td class="data-label">Documento</td><td class="data-val">{{nombre_documento}} ({{prefijo}})</td></tr>\n      {{fila_causa}}\n      <tr><td class="data-label">Fecha de registro</td><td class="data-val">{{fecha_registro}}</td></tr>\n      <tr><td class="data-label">Fecha de envío de la solicitud</td><td class="data-val">{{fecha_envio}}</td></tr>\n      <tr><td class="data-label">Correo electrónico notificado</td><td class="data-val">{{email_trabajador}}</td></tr>\n      <tr><td class="data-label">Celular registrado</td><td class="data-val">{{celular_trabajador}}</td></tr>\n      <tr><td class="data-label">Vigencia del enlace de firma</td><td class="data-val">{{token_expira}}</td></tr>\n      <tr><td class="data-label">Solicitado por</td><td class="data-val">{{creador}}</td></tr>\n    </table>\n  </div>\n\n  <div class="section-block">\n    <div class="section-title">Cierre como No firma</div>\n    <table class="data-grid">\n      <tr><td class="data-label">Fecha de cierre</td><td class="data-val">{{fecha_no_firma}}</td></tr>\n      <tr><td class="data-label">Cerrado por</td><td class="data-val">{{usuario_no_firma}}</td></tr>\n      <tr><td class="data-label">Anotación en el documento</td><td class="data-val annotation">{{anotacion}}</td></tr>\n    </table>\n  </div>\n\n  <div class="section-block">\n    <div class="section-title">Verificación</div>\n    <table class="data-grid">\n      <tr><td class="data-label">Código del registro</td><td class="data-val mono">{{id_registro}}</td></tr>\n      <tr><td class="data-label">Huella SHA-256 del documento enviado</td><td class="data-val mono">{{hash_original}}</td></tr>\n    </table>\n  </div>\n\n  <div class="note-box">\n    <p>El documento enviado al trabajador, con la anotación de soporte en el lugar de la firma, se conserva en los documentos del trabajador en Cloud Docs (<strong>{{prefijo}}</strong>).</p>\n    <p>La huella SHA-256 identifica de forma única el archivo enviado: si el archivo se modifica, la huella cambia. Soporte generado el <strong>{{fecha_generacion}}</strong>.</p>\n  </div>\n\n  <div class="doc-footer">\n    <div class="line"></div>\n    <div class="addr">DIAGONAL 74B No. 33° 51-55 — ANTIGUA TRANSVERSAL 39° No 70° 51-55 — LAURELES - MEDELLÍN</div>\n    <div class="legal">Apoyo Logístico y Operativo S.A.S. &bull; Documento electrónico — Ley 527 de 1999</div>\n  </div>\n\n</div>\n'
WHERE NOT EXISTS (SELECT 1 FROM Maestro_Plantillas WHERE nombre_proceso = 'soporte_no_firma');

INSERT INTO Config_Parametros (Modulo, Seccion, Concepto, Condicion, Parametro, Descripcion)
SELECT 'CloudDocs', 'LogySign', 'Documento de soporte de No firma', '', 'SSFD',
       'Prefijo de Config_Doc_Trabajador con el que se guarda en Cloud Docs el soporte de solicitud de firma digital que se genera al cerrar un documento como No firma (plantilla soporte_no_firma). Vacío: SSFD.'
WHERE NOT EXISTS (SELECT 1 FROM Config_Parametros WHERE Modulo = 'CloudDocs' AND Seccion = 'LogySign' AND Concepto = 'Documento de soporte de No firma');

UPDATE Config_Parametros
SET Parametro = 'Sistema',
    Descripcion = 'Roles (separados por coma) que pueden cerrar como No firma cualquier documento pendiente que vean y generar o regenerar su soporte. Quien creó el registro siempre puede hacerlo. Vacío: solo quien lo creó.'
WHERE Modulo = 'CloudDocs' AND Seccion = 'LogySign' AND Concepto = 'Roles que pueden marcar No firma'
  AND Parametro = 'Sistema, Juridica, Contratación';
